function disableLegacyCameraControls() {
    if (!config.disableLegacySystem) {
      if (config.debugMode) {
        console.log('[Camera] Legacy system left enabled (config.disableLegacySystem = false)')
      }
      return
    }

    try {
      // Access the world's camera controls system
      if (world.systems && world.systems.cameraControls) {
        legacyCameraControls = world.systems.cameraControls
        if (legacyCameraControls.disable) {
          legacyCameraControls.disable()
          console.log('[Camera] Legacy camera controls DISABLED to avoid conflicts')
        }
      }

      // Also try to disable through the world's direct reference
      if (world.cameraControls && world.cameraControls.disable) {
        world.cameraControls.disable()
        console.log('[Camera] World camera controls DISABLED')
      }
    } catch (e) {
      console.warn('[Camera] Could not disable legacy camera controls:', e)
    }
  }

function enableLegacyCameraControls() {
    try {
      if (legacyCameraControls && legacyCameraControls.enable) {
        legacyCameraControls.enable()
        console.log('[Camera] Legacy camera controls ENABLED')
      }

      if (world.cameraControls && world.cameraControls.enable) {
        world.cameraControls.enable()
        console.log('[Camera] World camera controls ENABLED')
      }
    } catch (e) {
      console.warn('[Camera] Could not enable legacy camera controls:', e)
    }
  }

function createPool(factory) {
  const pool = []
  return () => {
    if (pool.length) {
      return pool.pop()
    }
    const item = factory()
    item.release = () => pool.push(item)
    return item
  }
}

function activateHighestPriorityCamera() {
    if (cameras.length === 0) return

    let highestPriorityCamera = cameras[0]
    let highestPriority = cameras[0].priority || 0

    cameras.forEach(camera => {
      if (camera.priority > highestPriority) {
        highestPriority = camera.priority
        highestPriorityCamera = camera
      }
    })

    const cameraIndex = cameras.indexOf(highestPriorityCamera)
    if (cameraIndex !== -1) {
      currentCameraIndex = cameraIndex
      highestPriorityCamera.activate?.()

      if (settingsUI && settingsUI.currentInfo) {
        settingsUI.currentInfo.value = `Current: ${cameraPresets[currentCameraIndex].name}`
      }

      console.log(`[Camera] Activated highest priority camera: ${cameraPresets[currentCameraIndex].name}`)
    }
  }

function switchToCamera(cameraName) {
    if (!enhancedCameraSystem) return

    const camera = enhancedCameraSystem.getCamera(cameraName)
    if (camera) {
      enhancedCameraSystem.switchCamera(cameraName, 'smooth', 1.0)
      console.log(`[Camera] Switched to: ${CAMERA_PRESETS[cameraName]?.name || cameraName}`)
    } else {
      console.warn(`[Camera] Camera '${cameraName}' not found`)
    }
  }

function cycleCameras(reverse = false) {
    if (!enhancedCameraSystem) return

    const cameraList = enhancedCameraSystem.listCameras()
    if (cameraList.length === 0) return

    const activeCamera = enhancedCameraSystem.getActiveCamera()
    const currentIndex = activeCamera ? cameraList.indexOf(activeCamera.name) : -1

    let nextIndex
    if (reverse) {
      nextIndex = currentIndex <= 0 ? cameraList.length - 1 : currentIndex - 1
    } else {
      nextIndex = currentIndex >= cameraList.length - 1 ? 0 : currentIndex + 1
    }

    const nextCameraName = cameraList[nextIndex]
    enhancedCameraSystem.switchCamera(nextCameraName, 'smooth', 0.5)
    console.log(`[Camera] Cycled to: ${CAMERA_PRESETS[nextCameraName]?.name || nextCameraName}`)
  }

function toggleAllFeeds() {
    cameras.forEach((camera, index) => {
      if (camera && camera.setFeedEnabled) {
        camera.setFeedEnabled(!camera.feed?.enabled)
        console.log(`[Camera] Feed ${camera.feed?.enabled ? 'ENABLED' : 'DISABLED'} for camera ${index}`)
      }
    })
  }

