            while (n && n !== glb.scene) {
              const p = n.parent
              if (!p) break
              const i = p.children.indexOf(n)
              if (i < 0) break
              path.push(i)
              n = p
            }
            if (n === glb.scene) {
              path.reverse()
              let m = vrm.scene
