function toRGB(color) {
  try {
    color1.set(color)
    return [color1.r, color1.g, color1.b]
  } catch (error) {
    // If parsing fails, default to white and warn
    console.warn(`[particles] color '${color}' could not be parsed, using white instead.`)
    return [1, 1, 1]
  }
}

