    t = Math.max(0, Math.min(1, t))
    let lo = -1
    let hi = this.keyframes.length
    while (hi - lo > 1) {
      let mid = Math.round((lo + hi) / 2)
      if (this.keyframes[mid].time <= t) lo = mid
      else hi = mid
    }
    if (this.keyframes[lo].time === t) hi = lo
    if (lo === hi) {
      if (lo === 0) hi++
      else lo--
    }
    arr1[0] = lo
    arr1[1] = hi
    return arr1
