export class Physics extends System {
  constructor(world) {
    super(world)
    this.scene = null
  }

  async init() {
    const info = await loadPhysX()
    this.version = info.version
    this.allocator = info.allocator
    this.errorCb = info.errorCb
    this.foundation = info.foundation

    // Only extend THREE.js if not already extended
    if (typeof THREE !== 'undefined' && THREE.Vector3 && !THREE.Vector3.prototype.toPxVec3) {
      extendThreePhysX()
    }

    this.tolerances = new PHYSX.PxTolerancesScale()
    this.cookingParams = new PHYSX.PxCookingParams(this.tolerances)
    this.physics = PHYSX.CreatePhysics(this.version, this.foundation, this.tolerances)
    this.defaultMaterial = this.physics.createMaterial(0.2, 0.2, 0.2)

    this.callbackQueue = []

    this.getContactCallback = createPool(() => {
      const contactPool = []
      const contacts = []
      let idx = 0
      return {
        start: false,
        fn0: null,
        event0: {
          tag: null,
          playerId: null,
          contacts,
        },
        fn1: null,
        event1: {
          tag: null,
          playerId: null,
          contacts,
        },
        addContact(position, normal, impulse) {
          if (!contactPool[idx]) {
            contactPool[idx] = {
              position: new THREE.Vector3(),
              normal: new THREE.Vector3(),
              impulse: new THREE.Vector3(),
            }
          }
          const contact = contactPool[idx]
          contact.position.copy(position)
          contact.normal.copy(normal)
          contact.impulse.copy(impulse)
          contacts.push(contact)
          idx++
        },
        init(start) {
          this.start = start
          this.fn0 = null
          this.fn1 = null
          contacts.length = 0
          idx = 0
          return this
        },
        exec() {
          if (this.fn0) {
            try {
              this.fn0(this.event0)
            } catch (err) {
              console.error(err)
            }
          }
          if (this.fn1) {
            try {
              this.fn1(this.event1)
            } catch (err) {
              console.error(err)
            }
          }
          this.release()
        },
      }
    })
    this.contactCallbacks = []
    this.queueContactCallback = cb => {
      this.contactCallbacks.push(cb)
    }
    this.processContactCallbacks = () => {
      for (const cb of this.contactCallbacks) {
        cb.exec()
      }
      this.contactCallbacks.length = 0
    }
    const contactPoints = new PHYSX.PxArray_PxContactPairPoint(64)
    const simulationEventCallback = new PHYSX.PxSimulationEventCallbackImpl()
    simulationEventCallback.onContact = (pairHeader, pairs, count) => {
      pairHeader = PHYSX.wrapPointer(pairHeader, PHYSX.PxContactPairHeader)
      const handle0 = this.handles.get(pairHeader.get_actors(0)?.ptr)
      const handle1 = this.handles.get(pairHeader.get_actors(1)?.ptr)
      if (!handle0 || !handle1) return
      for (let i = 0; i < count; i++) {
        const pair = PHYSX.NativeArrayHelpers.prototype.getContactPairAt(pairs, i)
        if (pair.events.isSet(PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_FOUND)) {
          const contactCallback = this.getContactCallback().init(true)
          this.contactCallbacks.push(contactCallback)
          const pxContactPoints = pair.extractContacts(contactPoints.begin(), 64)
          if (pxContactPoints > 0) {
            for (let j = 0; j < pxContactPoints; j++) {
              const contact = contactPoints.get(j)
              contactCallback.addContact(contact.position, contact.normal, contact.impulse)
            }
          }
          if (!handle0.contactedHandles.has(handle1)) {
            if (handle0.onContactStart) {
              contactCallback.fn0 = handle0.onContactStart
              contactCallback.event0.tag = handle1.tag
              contactCallback.event0.playerId = handle1.playerId
            }
            handle0.contactedHandles.add(handle1)
          }
          if (!handle1.contactedHandles.has(handle0)) {
            if (handle1.onContactStart) {
              contactCallback.fn1 = handle1.onContactStart
              contactCallback.event1.tag = handle0.tag
              contactCallback.event1.playerId = handle0.playerId
            }
            handle1.contactedHandles.add(handle0)
          }
        } else if (pair.events.isSet(PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_LOST)) {
          const contactCallback = this.getContactCallback().init(false)
          this.contactCallbacks.push(contactCallback)
          if (handle0.contactedHandles.has(handle1)) {
            if (handle0.onContactEnd) {
              contactCallback.fn0 = handle0.onContactEnd
              contactCallback.event0.tag = handle1.tag
              contactCallback.event0.playerId = handle1.playerId
            }
            handle0.contactedHandles.delete(handle1)
          }
          if (handle1.contactedHandles.has(handle0)) {
            if (handle1.onContactEnd) {
              contactCallback.fn1 = handle1.onContactEnd
              contactCallback.event1.tag = handle0.tag
              contactCallback.event1.playerId = handle0.playerId
            }
            handle1.contactedHandles.delete(handle0)
          }
        }
      }
    }
    this.getTriggerCallback = createPool(() => {
      return {
        fn: null,
        event: {
          tag: null,
          playerId: null,
        },
        exec() {
          try {
            this.fn(this.event)
          } catch (err) {
            console.error(err)
          }
          this.release()
        },
      }
    })
    this.triggerCallbacks = []
    this.queueTriggerCallback = cb => {
      this.triggerCallbacks.push(cb)
    }
    this.processTriggerCallbacks = () => {
      for (const cb of this.triggerCallbacks) {
        cb.exec()
      }
      this.triggerCallbacks.length = 0
    }
    simulationEventCallback.onTrigger = (pairs, count) => {
      pairs = PHYSX.wrapPointer(pairs, PHYSX.PxTriggerPair)
      for (let i = 0; i < count; i++) {
        const pair = PHYSX.NativeArrayHelpers.prototype.getTriggerPairAt(pairs, i)
        // ignore pairs if a shape was deleted.
        // this prevents an issue where onLeave can get called after rebuilding an object that had entered a trigger
        if (
          pair.flags.isSet(PHYSX.PxTriggerPairFlagEnum.eREMOVED_SHAPE_TRIGGER) ||
          pair.flags.isSet(PHYSX.PxTriggerPairFlagEnum.eREMOVED_SHAPE_OTHER)
        ) {
          continue
        }
        const triggerHandle = this.handles.get(pair.triggerShape.getActor().ptr)
        const otherHandle = this.handles.get(pair.otherShape.getActor().ptr)
        if (!triggerHandle || !otherHandle) continue
        if (pair.status === PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_FOUND) {
          if (!otherHandle.triggeredHandles.has(triggerHandle)) {
            if (triggerHandle.onTriggerEnter) {
              const cb = this.getTriggerCallback()
              cb.fn = triggerHandle.onTriggerEnter
              cb.event.tag = otherHandle.tag
              cb.event.playerId = otherHandle.playerId
              this.triggerCallbacks.push(cb)
            }
            otherHandle.triggeredHandles.add(triggerHandle)
          }
        } else if (pair.status === PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_LOST) {
          if (otherHandle.triggeredHandles.has(triggerHandle)) {
            if (triggerHandle.onTriggerLeave) {
              const cb = this.getTriggerCallback()
              cb.fn = triggerHandle.onTriggerLeave
              cb.event.tag = otherHandle.tag
              cb.event.playerId = otherHandle.playerId
              this.triggerCallbacks.push(cb)
            }
            otherHandle.triggeredHandles.delete(triggerHandle)
          }
        }
      }
    }
    simulationEventCallback.onConstraintBreak = (...args) => {
      console.error('TODO: onContraintBreak', ...args)
    }

    const sceneDesc = new PHYSX.PxSceneDesc(this.tolerances)
    sceneDesc.gravity = new PHYSX.PxVec3(0, -9.81, 0)
    sceneDesc.cpuDispatcher = PHYSX.DefaultCpuDispatcherCreate(0)
    sceneDesc.filterShader = PHYSX.DefaultFilterShader()
    sceneDesc.flags.raise(PHYSX.PxSceneFlagEnum.eENABLE_CCD, true)
    sceneDesc.flags.raise(PHYSX.PxSceneFlagEnum.eENABLE_ACTIVE_ACTORS, true)
    sceneDesc.solverType = PHYSX.PxSolverTypeEnum.eTGS // recommened, default is PGS still
    sceneDesc.simulationEventCallback = simulationEventCallback
    sceneDesc.broadPhaseType = PHYSX.PxBroadPhaseTypeEnum.eGPU
    this.scene = this.physics.createScene(sceneDesc)

    this.handles = new Map()
    this.active = new Set()

    this.materials = {}

    this.raycastResult = new PHYSX.PxRaycastResult()
    this.sweepPose = new PHYSX.PxTransform(PHYSX.PxIDENTITYEnum.PxIdentity)
    this.sweepResult = new PHYSX.PxSweepResult()
    this.overlapPose = new PHYSX.PxTransform(PHYSX.PxIDENTITYEnum.PxIdentity)
    this.overlapResult = new PHYSX.PxOverlapResult()
    this.queryFilterData = new PHYSX.PxQueryFilterData()

    this._pv1 = new PHYSX.PxVec3()
    this._pv2 = new PHYSX.PxVec3()
    this.transform = new PHYSX.PxTransform(PHYSX.PxIDENTITYEnum.PxIdentity)

    this.setupControllerManager()
  }

  setupControllerManager() {
    this.controllerManager = PHYSX.PxTopLevelFunctions.prototype.CreateControllerManager(this.scene) // prettier-ignore
    this.controllerFilters = new PHYSX.PxControllerFilters()
    this.controllerFilters.mFilterData = new PHYSX.PxFilterData(Layers.player.group, Layers.player.mask, 0, 0) // prettier-ignore
    const filterCallback = new PHYSX.PxQueryFilterCallbackImpl()
    filterCallback.simplePreFilter = (filterDataPtr, shapePtr, actor) => {
      const filterData = PHYSX.wrapPointer(filterDataPtr, PHYSX.PxFilterData)
      const shape = PHYSX.wrapPointer(shapePtr, PHYSX.PxShape)
      const shapeFilterData = shape.getQueryFilterData()
      // if (0 == (filterData.word0 & shapeFilterData.word1) && 0 == (shapeFilterData.word0 & filterData.word1)) {
      //   return PHYSX.PxQueryHitType.eBLOCK
      //   return PHYSX.PxQueryHitType.eNONE
      // }
      if (filterData.word0 & shapeFilterData.word1 && shapeFilterData.word0 & filterData.word1) {
        return PHYSX.PxQueryHitType.eBLOCK
      }
      return PHYSX.PxQueryHitType.eNONE
    }
    this.controllerFilters.mFilterCallback = filterCallback
    const cctFilterCallback = new PHYSX.PxControllerFilterCallbackImpl()
    cctFilterCallback.filter = (aPtr, bPtr) => {
      // const a = PHYSX.wrapPointer(aPtr, PHYSX.PxCapsuleController)
      // const b = PHYSX.wrapPointer(bPtr, PHYSX.PxCapsuleController)
      return true // for now ALL cct's collide
    }
    this.controllerFilters.mCCTFilterCallback = cctFilterCallback
  }

  start() {
    // ...
  }

  addActor(actor, handle) {
    handle.actor = actor
    handle.contactedHandles = new Set()
    handle.triggeredHandles = new Set()
    if (handle.onInterpolate) {
      handle.interpolation = {
        prev: {
          position: new THREE.Vector3(),
          quaternion: new THREE.Quaternion(),
        },
        next: {
          position: new THREE.Vector3(),
          quaternion: new THREE.Quaternion(),
        },
        curr: {
          position: new THREE.Vector3(),
          quaternion: new THREE.Quaternion(),
        },
      }
      const pose = actor.getGlobalPose()
      handle.interpolation.prev.position.copy(pose.p)
      handle.interpolation.prev.quaternion.copy(pose.q)
      handle.interpolation.next.position.copy(pose.p)
      handle.interpolation.next.quaternion.copy(pose.q)
      handle.interpolation.curr.position.copy(pose.p)
      handle.interpolation.curr.quaternion.copy(pose.q)
    }
    this.handles.set(actor.ptr, handle)
    if (!handle.controller) {
      this.scene.addActor(actor)
    }
    return {
      move: matrix => {
        if (this.ignoreSetGlobalPose) {
          const isDynamic = !actor.getRigidBodyFlags?.().isSet(PHYSX.PxRigidBodyFlagEnum.eKINEMATIC)
          if (isDynamic) return
          return
        }
        matrix.toPxTransform(this.transform)
        actor.setGlobalPose(this.transform)
      },
      snap: pose => {
        actor.setGlobalPose(pose)
        handle.interpolation.prev.position.copy(pose.p)
        handle.interpolation.prev.quaternion.copy(pose.q)
        handle.interpolation.next.position.copy(pose.p)
        handle.interpolation.next.quaternion.copy(pose.q)
        handle.interpolation.curr.position.copy(pose.p)
        handle.interpolation.curr.quaternion.copy(pose.q)
        handle.interpolation.skip = true
      },
      destroy: () => {
        // end any contacts
        if (handle.contactedHandles.size) {
          const cb = this.getContactCallback().init(false)
          for (const otherHandle of handle.contactedHandles) {
            if (otherHandle.onContactEnd) {
              cb.fn0 = otherHandle.onContactEnd
              cb.event0.tag = handle.tag
              cb.event0.playerId = handle.playerId
              cb.exec()
            }
            otherHandle.contactedHandles.delete(handle)
          }
        }
        // end any triggers
        if (handle.triggeredHandles.size) {
          const cb = this.getTriggerCallback()
          for (const triggerHandle of handle.triggeredHandles) {
            if (triggerHandle.onTriggerLeave) {
              cb.fn = triggerHandle.onTriggerLeave
              cb.event.tag = handle.tag
              cb.event.playerId = handle.playerId
              cb.exec()
            }
          }
        }
        // remove from scene
        if (!handle.controller) {
          this.scene.removeActor(actor)
        }
        // delete data
        this.handles.delete(actor.ptr)
      },
    }
  }

  preFixedUpdate(willFixedUpdate) {
    if (willFixedUpdate) {
      // if physics will step, clear active actors so we can repopulate.
      this.active.clear()
    }
  }

  postFixedUpdate(delta) {
    this.scene.simulate(delta)
    this.scene.fetchResults(true)
    this.processContactCallbacks()
    this.processTriggerCallbacks()
    const activeActors = PHYSX.SupportFunctions.prototype.PxScene_getActiveActors(this.scene)
    const size = activeActors.size()
    for (let i = 0; i < size; i++) {
      const actorPtr = activeActors.get(i).ptr
      const handle = this.handles.get(actorPtr)
      if (!handle) {
        // todo: addBot vrms do this
        // console.warn('active actor not found?', actorPtr)
        continue
      }
      const lerp = handle.interpolation
      if (!lerp) continue
      lerp.prev.position.copy(lerp.next.position)
      lerp.prev.quaternion.copy(lerp.next.quaternion)
      const pose = handle.actor.getGlobalPose()
      lerp.next.position.copy(pose.p)
      lerp.next.quaternion.copy(pose.q)
      this.active.add(handle)
    }
  }

  preUpdate(alpha) {
    for (const handle of this.active) {
      const lerp = handle.interpolation
      if (lerp.skip) {
        lerp.skip = false
        continue
      }
      lerp.curr.position.lerpVectors(lerp.prev.position, lerp.next.position, alpha)
      lerp.curr.quaternion.slerpQuaternions(lerp.prev.quaternion, lerp.next.quaternion, alpha)
      handle.onInterpolate(lerp.curr.position, lerp.curr.quaternion)
    }
    // finalize any physics updates immediately
    // but don't listen to any loopback commits from those actor moves
    this.ignoreSetGlobalPose = true
    this.world.stage.clean()
    this.ignoreSetGlobalPose = false
  }

  raycast(origin, direction, maxDistance = Infinity, layerMask) {
    if (!origin.toPxVec3 || !direction.toPxVec3) {
      console.warn('Physics.raycast called before THREE.js extensions loaded')
      return null
    }
    origin = origin.toPxVec3(this._pv1)
    direction = direction.toPxVec3(this._pv2)
    // this.queryFilterData.flags |= PHYSX.PxQueryFlagEnum.ePREFILTER | PHYSX.PxQueryFlagEnum.ePOSTFILTER // prettier-ignore
    this.queryFilterData.data.word0 = layerMask // what to hit, eg Layers.player.group | Layers.environment.group
    this.queryFilterData.data.word1 = 0
    const didHit = this.scene.raycast(
      origin,
      direction,
      maxDistance,
      this.raycastResult,
      PHYSX.PxHitFlagEnum.eNORMAL,
      this.queryFilterData
    )
    if (didHit) {
      const numHits = this.raycastResult.getNbAnyHits()
      let hit
      for (let n = 0; n < numHits; n++) {
        const nHit = this.raycastResult.getAnyHit(n)
        if (!hit || hit.distance > nHit.distance) {
          hit = nHit
        }
      }
      _raycastHit.handle = this.handles.get(hit.actor.ptr)
      _raycastHit.point.set(hit.position.x, hit.position.y, hit.position.z)
      _raycastHit.normal.set(hit.normal.x, hit.normal.y, hit.normal.z)
      _raycastHit.distance = hit.distance
      return _raycastHit
    }
    // TODO: this.raycastResult.destroy() on this.destroy()
  }

  sweep(geometry, origin, direction, maxDistance, layerMask) {
    if (!origin.toPxVec3 || !direction.toPxVec3) {
      console.warn('Physics.sweep called before THREE.js extensions loaded')
      return null
    }
    origin.toPxVec3(this.sweepPose.p)
    direction = direction.toPxVec3(this._pv2)
    this.queryFilterData.data.word0 = layerMask
    this.queryFilterData.data.word1 = 0
    const didHit = this.scene.sweep(
      geometry,
      this.sweepPose,
      direction,
      maxDistance,
      this.sweepResult,
      PHYSX.PxHitFlagEnum.eDEFAULT,
      this.queryFilterData
    )
    if (didHit) {
      const numHits = this.sweepResult.getNbAnyHits()
      let hit
      for (let n = 0; n < numHits; n++) {
        const nHit = this.sweepResult.getAnyHit(n)
        if (!hit || hit.distance > nHit.distance) {
          hit = nHit
        }
      }
      _sweepHit.actor = hit.actor
      _sweepHit.point.set(hit.position.x, hit.position.y, hit.position.z)
      _sweepHit.normal.set(hit.normal.x, hit.normal.y, hit.normal.z)
      _sweepHit.distance = hit.distance
      return _sweepHit
    }
    // TODO: this.sweepResult.destroy() on this.destroy()
  }

  // overlap(geometry, origin, layerMask) {
  //   origin.toPxVec3(this.overlapPose.p)
  //   this.queryFilterData.data.word0 = layerMask
  //   this.queryFilterData.data.word1 = 0
  //   const didHit = this.scene.overlap(geometry, this.overlapPose, this.overlapResult, this.queryFilterData)
  //   if (didHit) {
  //     // const hit = this.overlapResult.getAnyHit(0)
  //     _overlapHit.actor = hit.actor
  //     return _overlapHit
  //   }
  //   // TODO: this.overlapResult.destroy() on this.destroy()
  // }

  overlapSphere(radius, origin, layerMask) {
    if (!origin.toPxVec3) {
      console.warn('Physics.overlapSphere called before THREE.js extensions loaded')
      return []
    }
    origin.toPxVec3(this.overlapPose.p)
    const geometry = getSphereGeometry(radius)
    this.queryFilterData.data.word0 = layerMask // what to hit, eg Layers.player.group | Layers.environment.group
    this.queryFilterData.data.word1 = 0
    const didHit = this.scene.overlap(geometry, this.overlapPose, this.overlapResult, this.queryFilterData)
    if (!didHit) return []
    overlapHits.length = 0
    const numHits = this.overlapResult.getNbAnyHits()
    for (let n = 0; n < numHits; n++) {
      const nHit = this.overlapResult.getAnyHit(n)
      const hit = getOrCreateOverlapHit(n)
      hit.actor = nHit.actor
      hit.handle = this.handles.get(nHit.actor.ptr)
      overlapHits.push(hit)
    }
    return overlapHits
  }

  getMaterial(staticFriction, dynamicFriction, restitution) {
    // we cache and re-use material as PhysX has a limit of 64k.
    // this only works if the materials are not modified by the user, eg
    // players change friction coefficients etc
    // cached and re-used because PhysX has a limit of 64k
    const id = `${staticFriction}${dynamicFriction}${restitution}`
    let material = this.materials[id]
    if (!material) {
      material = this.physics.createMaterial(staticFriction, dynamicFriction, restitution)
      this.materials[id] = material
    }
    return material
  }
}

if (!material) {
  material = this.physics.createMaterial(staticFriction, dynamicFriction, restitution)
  this.materials[id] = material
}

export class PlatformerMechanics extends System {
  constructor(world) {
    super(world)
    this.activePlayers = new Map() // playerId -> platformer state
    this.grindRails = new Map() // railId -> rail data
    this.triggerColliders = new Map() // colliderId -> trigger data
  }

  init() {
    // Register for player events
    this.world.events.on('enter', this.onPlayerEnter.bind(this))
    this.world.events.on('leave', this.onPlayerLeave.bind(this))

    console.log('[PlatformerMechanics] System initialized')
  }

  onPlayerEnter({ playerId }) {
    this.activePlayers.set(playerId, {
      mode: PlatformerModes.NONE,
      stamina: StaminaConfig.MAX_STAMINA,
      grindRail: null,
      grindProgress: 0,
      grindSpeed: 0,
      climbWall: null,
      climbDirection: 0, // -1 down, 0 idle, 1 up
      ledgeHanging: false,
      ledgePosition: null,
      airDiving: false,
      diveMomentum: new THREE.Vector3(),
      wallSliding: false,
      wallNormal: new THREE.Vector3(),
      wallSlideSpeed: 0,
      lastUpdateTime: 0,
    })
  }

  onPlayerLeave({ playerId }) {
    this.activePlayers.delete(playerId)
  }

  // Grinding System
  createGrindRail(points, options = {}) {
    const railId = `rail_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`

    // Create CatmullRomCurve3 for smooth rail following
    const curve = new THREE.CatmullRomCurve3(points, options.closed || false, options.curveType || 'catmullrom', options.tension || 0.5)

    const railData = {
      id: railId,
      curve,
      points,
      speed: options.speed || 8,
      friction: options.friction || 0.95,
      triggerRadius: options.triggerRadius || 2,
      animation: options.animation || Emotes.GRINDING,
      active: true,
    }

    this.grindRails.set(railId, railData)

    // Create trigger collider for activation
    this.createGrindTrigger(railData)

    return railId
  }

  createGrindTrigger(railData) {
    const triggerId = `grind_trigger_${railData.id}`

    // Create sphere trigger collider at start of rail
    const geometry = new PHYSX.PxSphereGeometry(railData.triggerRadius)
    const material = this.world.physics.physics.createMaterial(0, 0, 0)
    const flags = new PHYSX.PxShapeFlags(PHYSX.PxShapeFlagEnum.eSCENE_QUERY_SHAPE | PHYSX.PxShapeFlagEnum.eTRIGGER_SHAPE)
    const shape = this.world.physics.physics.createShape(geometry, material, true, flags)

    const filterData = new PHYSX.PxFilterData(
      Layers.prop.group,
      Layers.player.mask,
      PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_FOUND | PHYSX.PxPairFlagEnum.eNOTIFY_TOUCH_LOST,
      0
    )
    shape.setQueryFilterData(filterData)
    shape.setSimulationFilterData(filterData)

    const transform = new PHYSX.PxTransform(PHYSX.PxIDENTITYEnum.PxIdentity)
    railData.points[0].toPxTransform(transform)

    const trigger = this.world.physics.physics.createRigidStatic(transform)
    trigger.attachShape(shape)

    const triggerData = {
      id: triggerId,
      railId: railData.id,
      actor: trigger,
      shape,
    }

    this.triggerColliders.set(triggerId, triggerData)
    this.world.physics.addActor(trigger, {
      tag: 'grind_trigger',
      railId: railData.id,
      onTouchFound: (otherHandle) => {
        if (otherHandle.playerId) {
          this.attemptGrindStart(otherHandle.playerId, railData.id)
        }
      },
    })

    return triggerId
  }

  attemptGrindStart(playerId, railId) {
    const player = this.world.entities.get(playerId)
    if (!player || !player.isLocal) return

    const state = this.activePlayers.get(playerId)
    if (!state || state.mode !== PlatformerModes.NONE) return

    const rail = this.grindRails.get(railId)
    if (!rail || !rail.active) return

    // Check if player is moving fast enough and in the right direction
    const velocity = player.capsule.getLinearVelocity()
    const speed = new THREE.Vector3(velocity.x, velocity.y, velocity.z).length()

    if (speed < 3) return // Need minimum speed to start grinding

    // Start grinding
    this.startGrinding(playerId, railId)
  }

  startGrinding(playerId, railId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)
    const rail = this.grindRails.get(railId)

    if (!state || !player || !rail) return

    state.mode = PlatformerModes.GRINDING
    state.grindRail = rail
    state.grindProgress = 0
    state.grindSpeed = rail.speed

    // Set platformer mode on player
    player.setPlatformerMode(PlatformerModes.GRINDING)

    // Disable physics simulation for grinding
    player.capsule.setActorFlag(PHYSX.PxActorFlagEnum.eDISABLE_SIMULATION, true)

    // Set animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(rail.animation)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} started grinding on rail ${railId}`)
  }

  updateGrinding(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.GRINDING) return

    const rail = state.grindRail
    if (!rail) {
      this.stopGrinding(playerId)
      return
    }

    // Drain stamina
    state.stamina -= StaminaConfig.GRINDING_DRAIN * delta
    if (state.stamina <= 0) {
      this.stopGrinding(playerId)
      return
    }

    // Update grind progress along curve
    const curveLength = rail.curve.getLength()
    const progressDelta = (state.grindSpeed * delta) / curveLength
    state.grindProgress += progressDelta

    // Check if reached end of rail
    if (state.grindProgress >= 1) {
      this.stopGrinding(playerId)
      return
    }

    // Get position and tangent from curve
    const position = rail.curve.getPointAt(state.grindProgress)
    const tangent = rail.curve.getTangentAt(state.grindProgress)

    // Update player position
    player.base.position.copy(position)

    // Orient player to face movement direction
    if (tangent.length() > 0) {
      const lookDirection = tangent.clone().normalize()
      const angle = Math.atan2(lookDirection.x, lookDirection.z)
      player.base.rotation.y = angle
    }

    // Apply friction to speed
    state.grindSpeed *= rail.friction

    // Check for input to jump off rail
    if (player.jumpPressed) {
      this.stopGrinding(playerId)
      // Apply jump force in tangent direction
      const jumpForce = tangent.clone().normalize().multiplyScalar(state.grindSpeed * 0.5)
      jumpForce.y = 8 // Add upward component
      player.pushForce = jumpForce
    }
  }

  stopGrinding(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.GRINDING) return

    // Re-enable physics simulation
    player.capsule.setActorFlag(PHYSX.PxActorFlagEnum.eDISABLE_SIMULATION, false)

    // Clear grinding state
    state.mode = PlatformerModes.NONE
    state.grindRail = null
    state.grindProgress = 0
    state.grindSpeed = 0

    // Reset platformer mode on player
    player.setPlatformerMode(PlatformerModes.NONE)

    // Clear animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(null)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} stopped grinding`)
  }

  // Climbing System
  updateClimbing(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.CLIMBING) return

    // Drain stamina
    state.stamina -= StaminaConfig.CLIMBING_DRAIN * delta
    if (state.stamina <= 0) {
      this.stopClimbing(playerId)
      return
    }

    // Check for wall in front
    const wallHit = this.checkWallInFront(player)
    if (!wallHit) {
      this.stopClimbing(playerId)
      return
    }

    // Handle climbing movement
    if (state.climbDirection !== 0) {
      const climbSpeed = 3
      const climbDirection = new THREE.Vector3(0, state.climbDirection, 0)
      const climbForce = climbDirection.multiplyScalar(climbSpeed * 10)

      // Apply climbing force
      player.capsule.addForce(climbForce.toPxVec3(), PHYSX.PxForceModeEnum.eFORCE, true)

      // Set animation based on direction
      let animation = Emotes.CLIMB_IDLE
      if (state.climbDirection > 0) {
        animation = Emotes.CLIMB_UP
      } else if (state.climbDirection < 0) {
        animation = Emotes.CLIMB_DOWN
      }

      if (player.avatar && player.avatar.setEmote) {
        player.avatar.setEmote(animation)
      }
    }
  }

  checkWallInFront(player) {
    const pose = player.capsule.getGlobalPose()
    const origin = new THREE.Vector3(pose.p.x, pose.p.y, pose.p.z)

    // Cast ray forward from player
    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(player.base.quaternion)
    const hitMask = Layers.environment.group | Layers.prop.group

    return this.world.physics.raycast(origin, forward, 1.5, hitMask)
  }

  attemptClimbStart(playerId) {
    try {
      const state = this.activePlayers.get(playerId)
      const player = this.world.entities.get(playerId)

      if (!state || !player || state.mode !== PlatformerModes.NONE) return
      if (state.stamina < 10) return // Need minimum stamina

    // Check for wall in front
    const wallHit = this.checkWallInFront(player)
    if (!wallHit) return

    // Check if wall is climbable (not too steep)
    const wallAngle = Math.acos(wallHit.normal.y) * (180 / Math.PI)
    if (wallAngle > 45) return // Too steep to climb

    // Start climbing
    state.mode = PlatformerModes.CLIMBING
    state.climbWall = wallHit
    state.climbDirection = 0

    // Set platformer mode on player
    player.setPlatformerMode(PlatformerModes.CLIMBING)

      console.log(`[PlatformerMechanics] Player ${playerId} started climbing`)
    } catch (error) {
      console.error('[PlatformerMechanics] Error in attemptClimbStart:', error)
    }
  }

  stopClimbing(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.CLIMBING) return

    state.mode = PlatformerModes.NONE
    state.climbWall = null
    state.climbDirection = 0

    // Reset platformer mode on player
    player.setPlatformerMode(PlatformerModes.NONE)

    // Clear animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(null)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} stopped climbing`)
  }

  // Ledge Detection System
  updateLedgeHanging(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.LEDGE_HANGING) return

    // Drain stamina
    state.stamina -= StaminaConfig.LEDGE_DRAIN * delta
    if (state.stamina <= 0) {
      this.stopLedgeHanging(playerId)
      return
    }

    // Check if still hanging on ledge
    if (!this.checkLedgeStillValid(player, state.ledgePosition)) {
      this.stopLedgeHanging(playerId)
      return
    }

    // Handle ledge movement
    if (state.climbDirection !== 0) {
      const ledgeSpeed = 2
      const moveDirection = new THREE.Vector3(state.climbDirection, 0, 0)
      const moveForce = moveDirection.multiplyScalar(ledgeSpeed * 10)

      // Apply horizontal movement force
      player.capsule.addForce(moveForce.toPxVec3(), PHYSX.PxForceModeEnum.eFORCE, true)

      // Set animation
      const animation = state.climbDirection !== 0 ? Emotes.LEDGE_HANGING_MOVING : Emotes.LEDGE_HANGING_IDLE
      if (player.avatar && player.avatar.setEmote) {
        player.avatar.setEmote(animation)
      }
    }
  }

  checkLedgeStillValid(player, ledgePosition) {
    if (!ledgePosition) return false

    // Check if player is still near the ledge
    const distance = player.base.position.distanceTo(ledgePosition)
    return distance < 1.5
  }

  attemptLedgeGrab(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.NONE) return
    if (state.stamina < 10) return

    // Check for ledge below player
    const ledgeHit = this.checkLedgeBelow(player)
    if (!ledgeHit) return

    // Start ledge hanging
    state.mode = PlatformerModes.LEDGE_HANGING
    state.ledgePosition = ledgeHit.point.clone()
    state.climbDirection = 0

    // Set platformer mode on player
    player.setPlatformerMode(PlatformerModes.LEDGE_HANGING)

    // Position player at ledge
    player.base.position.copy(ledgeHit.point)
    player.base.position.y += 0.5 // Adjust height

    console.log(`[PlatformerMechanics] Player ${playerId} grabbed ledge`)
  }

  checkLedgeBelow(player) {
    const pose = player.capsule.getGlobalPose()
    const origin = new THREE.Vector3(pose.p.x, pose.p.y - 1, pose.p.z)

    // Cast ray downward
    const down = new THREE.Vector3(0, -1, 0)
    const hitMask = Layers.environment.group | Layers.prop.group

    return this.world.physics.raycast(origin, down, 2, hitMask)
  }

  stopLedgeHanging(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.LEDGE_HANGING) return

    state.mode = PlatformerModes.NONE
    state.ledgePosition = null
    state.climbDirection = 0

    // Reset platformer mode on player
    player.setPlatformerMode(PlatformerModes.NONE)

    // Clear animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(null)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} released ledge`)
  }

  // Air Diving System
  updateAirDiving(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.AIR_DIVING) return

    // Apply dive momentum
    if (state.diveMomentum.length() > 0) {
      const diveForce = state.diveMomentum.clone().multiplyScalar(10)
      player.capsule.addForce(diveForce.toPxVec3(), PHYSX.PxForceModeEnum.eFORCE, true)

      // Apply friction to momentum
      state.diveMomentum.multiplyScalar(0.95)

      // Stop diving when momentum is low
      if (state.diveMomentum.length() < 0.1) {
        this.stopAirDiving(playerId)
      }
    }
  }

  attemptAirDive(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.NONE) return
    if (player.grounded) return // Must be in air

    // Get current velocity
    const velocity = player.capsule.getLinearVelocity()
    const currentVelocity = new THREE.Vector3(velocity.x, velocity.y, velocity.z)

    // Calculate dive direction (forward + down)
    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(player.base.quaternion)
    const diveDirection = forward.clone().multiplyScalar(0.7).add(new THREE.Vector3(0, -0.3, 0))

    // Start air diving
    state.mode = PlatformerModes.AIR_DIVING
    state.diveMomentum = diveDirection.multiplyScalar(15) // Initial dive force

    // Set platformer mode on player
    player.setPlatformerMode(PlatformerModes.AIR_DIVING)

    // Set animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(Emotes.AIR_DIVE)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} started air diving`)
  }

  stopAirDiving(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.AIR_DIVING) return

    state.mode = PlatformerModes.NONE
    state.diveMomentum.set(0, 0, 0)

    // Reset platformer mode on player
    player.setPlatformerMode(PlatformerModes.NONE)

    // Clear animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(null)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} stopped air diving`)
  }

  // Wall Sliding System
  updateWallSliding(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.WALL_SLIDING) return

    // Drain stamina
    state.stamina -= StaminaConfig.WALL_SLIDE_DRAIN * delta
    if (state.stamina <= 0) {
      this.stopWallSliding(playerId)
      return
    }

    // Check if still against wall
    const wallHit = this.checkWallInFront(player)
    if (!wallHit) {
      this.stopWallSliding(playerId)
      return
    }

    // Apply wall slide physics
    const velocity = player.capsule.getLinearVelocity()
    const currentVelocity = new THREE.Vector3(velocity.x, velocity.y, velocity.z)

    // Reduce downward velocity for wall sliding
    const slideVelocity = currentVelocity.clone()
    slideVelocity.y = Math.max(slideVelocity.y, -3) // Cap fall speed

    // Apply wall slide force
    const slideForce = new THREE.Vector3(0, -2, 0) // Gentle downward force
    player.capsule.addForce(slideForce.toPxVec3(), PHYSX.PxForceModeEnum.eFORCE, true)

    // Set animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(Emotes.WALL_SLIDE)
    }
  }

  attemptWallSlide(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.NONE) return
    if (player.grounded) return // Must be in air

    // Check for wall in front
    const wallHit = this.checkWallInFront(player)
    if (!wallHit) return

    // Check if wall is slideable (not too steep)
    const wallAngle = Math.acos(wallHit.normal.y) * (180 / Math.PI)
    if (wallAngle < 30) return // Too flat to slide

    // Start wall sliding
    state.mode = PlatformerModes.WALL_SLIDING
    state.wallNormal = wallHit.normal.clone()
    state.wallSlideSpeed = 0

    // Set platformer mode on player
    player.setPlatformerMode(PlatformerModes.WALL_SLIDING)

    console.log(`[PlatformerMechanics] Player ${playerId} started wall sliding`)
  }

  stopWallSliding(playerId) {
    const state = this.activePlayers.get(playerId)
    const player = this.world.entities.get(playerId)

    if (!state || !player || state.mode !== PlatformerModes.WALL_SLIDING) return

    state.mode = PlatformerModes.NONE
    state.wallNormal.set(0, 0, 0)
    state.wallSlideSpeed = 0

    // Reset platformer mode on player
    player.setPlatformerMode(PlatformerModes.NONE)

    // Clear animation
    if (player.avatar && player.avatar.setEmote) {
      player.avatar.setEmote(null)
    }

    console.log(`[PlatformerMechanics] Player ${playerId} stopped wall sliding`)
  }

  // Input handling
  handlePlayerInput(playerId, input) {
    const state = this.activePlayers.get(playerId)
    if (!state) return

    switch (state.mode) {
      case PlatformerModes.CLIMBING:
        if (input.climbUp) state.climbDirection = 1
        else if (input.climbDown) state.climbDirection = -1
        else state.climbDirection = 0
        break

      case PlatformerModes.LEDGE_HANGING:
        if (input.moveLeft) state.climbDirection = -1
        else if (input.moveRight) state.climbDirection = 1
        else state.climbDirection = 0
        break
    }
  }

  // Stamina regeneration
  updateStamina(playerId, delta) {
    const state = this.activePlayers.get(playerId)
    if (!state) return

    // Regenerate stamina when not using mechanics
    if (state.mode === PlatformerModes.NONE && state.stamina < StaminaConfig.MAX_STAMINA) {
      state.stamina = Math.min(StaminaConfig.MAX_STAMINA, state.stamina + StaminaConfig.REGEN_RATE * delta)
    }
  }

  // Main update loop
  fixedUpdate(delta) {
    for (const [playerId, state] of this.activePlayers) {
      this.updateStamina(playerId, delta)

      switch (state.mode) {
        case PlatformerModes.GRINDING:
          this.updateGrinding(playerId, delta)
          break
        case PlatformerModes.CLIMBING:
          this.updateClimbing(playerId, delta)
          break
        case PlatformerModes.LEDGE_HANGING:
          this.updateLedgeHanging(playerId, delta)
          break
        case PlatformerModes.AIR_DIVING:
          this.updateAirDiving(playerId, delta)
          break
        case PlatformerModes.WALL_SLIDING:
          this.updateWallSliding(playerId, delta)
          break
      }

      // Send network updates for platformer state
      this.sendPlatformerState(playerId, state)
    }
  }

  // Network synchronization
  sendPlatformerState(playerId, state) {
    if (!this.world.network) return

    const player = this.world.entities.get(playerId)
    if (!player || !player.isLocal) return

    // Only send if state has changed significantly
    const now = this.world.time
    if (now - state.lastUpdateTime < 0.1) return // Throttle updates

    const platformerData = {
      playerId,
      mode: state.mode,
      stamina: Math.round(state.stamina),
      grindProgress: state.grindProgress,
      grindSpeed: state.grindSpeed,
      climbDirection: state.climbDirection,
      diveMomentum: state.diveMomentum.toArray(),
      wallSlideSpeed: state.wallSlideSpeed,
    }

    this.world.network.send('platformerState', platformerData)
    state.lastUpdateTime = now
  }

  onPlatformerState(data) {
    const { playerId, mode, stamina, grindProgress, grindSpeed, climbDirection, diveMomentum, wallSlideSpeed } = data

    const state = this.activePlayers.get(playerId)
    if (!state) return

    // Update remote player state
    state.mode = mode
    state.stamina = stamina
    state.grindProgress = grindProgress
    state.grindSpeed = grindSpeed
    state.climbDirection = climbDirection
    state.diveMomentum.fromArray(diveMomentum)
    state.wallSlideSpeed = wallSlideSpeed

    // Update player entity
    const player = this.world.entities.get(playerId)
    if (player) {
      player.setPlatformerMode(mode)
      player.setStamina(stamina)
    }
  }

  onPlatformerAction(data) {
    const { playerId, action, params } = data

    switch (action) {
      case 'startGrinding':
        this.startGrinding(playerId, params.railId)
        break
      case 'stopGrinding':
        this.stopGrinding(playerId)
        break
      case 'startClimbing':
        this.attemptClimbStart(playerId)
        break
      case 'stopClimbing':
        this.stopClimbing(playerId)
        break
      case 'startLedgeHanging':
        this.attemptLedgeGrab(playerId)
        break
      case 'stopLedgeHanging':
        this.stopLedgeHanging(playerId)
        break
      case 'startAirDiving':
        this.attemptAirDive(playerId)
        break
      case 'stopAirDiving':
        this.stopAirDiving(playerId)
        break
      case 'startWallSliding':
        this.attemptWallSlide(playerId)
        break
      case 'stopWallSliding':
        this.stopWallSliding(playerId)
        break
    }
  }

  // Cleanup
  destroy() {
    this.world.events.off('enter', this.onPlayerEnter.bind(this))
    this.world.events.off('leave', this.onPlayerLeave.bind(this))

    // Clean up grind rails and triggers
    for (const [triggerId, triggerData] of this.triggerColliders) {
      this.world.physics.removeActor(triggerData.actor)
    }

    this.activePlayers.clear()
    this.grindRails.clear()
    this.triggerColliders.clear()
  }
}

for (const [triggerId, triggerData] of this.triggerColliders) {
  this.world.physics.removeActor(triggerData.actor)
}

export class Scripts extends System {
  constructor(world) {
    super(world)
    this.compartment = new Compartment({
      console: {
        log: (...args) => console.log(...args),
        warn: (...args) => console.warn(...args),
        error: (...args) => console.error(...args),
        time: (...args) => console.time(...args),
        timeEnd: (...args) => console.timeEnd(...args),
      },
